WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_bg_gap'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '插空法', 'kp-pc-bg-gap', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "插空法（不相邻限制）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "要求必须【不相邻】的元素，绝对不能先排它们！让别人先排好，它们再插进别人产生的空隙里。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙丙三人互不相邻”、“不能有连续的两名男生”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[把没有限制的 n 个普通元素先排好队伍] --> B[计算普通元素排队的方法数 A(n,n)]\nB --> C[数出这 n 个普通元素队伍产生的所有空隙数 (含两端, 共 n+1 个空隙)]\nC --> D[把要求不相邻的 m 个特殊元素插入这些空隙中 A(n+1, m)]\nD --> E[总方法数 = 普通排列 × 插空排列]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 3 男 4 女排队，要求 3 名男生绝对不相邻，有几种排法？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先排女生：4 名女生全排列，A(4,4) = 24 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找空隙：4 名女生排好后，前后加上中间共有 5 个空隙（_女_女_女_女_）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "男生插空：3 名男生插入这 5 个空隙，A(5,3) = 5×4×3 = 60 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总计：24 × 60 = 1440 种。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "两端空隙漏算：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "4 个人排队，中间只有 3 个缝，但头尾还有 2 个空！总共绝对是 5 个空！记住：n 个人排队，产生 n+1 个空隙。"}]}]}]}$$ AS jsonb), NULL, '插空法的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "插空法"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_bg_gap", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
